INSERT INTO `sys_list_config` (`id`, `resource_code`, `resource_name`, `endpoint`, `page_size`, `columns_json`, `query_json`, `actions_json`, `form_json`, `page_json`, `dialog_json`, `status`, `remark`, `created_at`, `created_by`, `updated_at`, `updated_by`, `deleted`) VALUES (1,'system-users','用户管理','/system/users/page',10,'[{\"prop\":\"username\",\"label\":\"账号\",\"width\":150},{\"prop\":\"displayName\",\"label\":\"显示名称\",\"minWidth\":140},{\"prop\":\"institutionId\",\"label\":\"机构\",\"minWidth\":140,\"renderer\":\"institutionName\"},{\"prop\":\"phone\",\"label\":\"手机号\",\"width\":140},{\"prop\":\"roleCodes\",\"label\":\"角色\",\"minWidth\":160,\"type\":\"tags\"},{\"prop\":\"status\",\"label\":\"状态\",\"width\":120,\"type\":\"dict\",\"dictType\":\"common_status\",\"tagTypeMap\":{\"active\":\"success\",\"disabled\":\"info\"}},{\"prop\":\"passwordResetRequired\",\"label\":\"密码状态\",\"width\":140,\"renderer\":\"passwordStatus\"},{\"prop\":\"lastLoginAt\",\"label\":\"最近登录\",\"width\":180,\"type\":\"datetime\"},{\"prop\":\"remark\",\"label\":\"备注\",\"minWidth\":180}]','[{\"field\":\"keyword\",\"label\":\"关键字\",\"type\":\"input\",\"placeholder\":\"账号/显示名称/手机号\"},{\"field\":\"status\",\"label\":\"状态\",\"type\":\"dict-select\",\"dictType\":\"common_status\"},{\"field\":\"institutionId\",\"label\":\"机构\",\"type\":\"select\",\"optionsLoader\":\"institutions\"}]','[{\"action\":\"user-create\",\"label\":\"新增用户\",\"position\":\"toolbar\",\"buttonType\":\"primary\",\"permission\":\"system:user:manage\"},{\"action\":\"user-edit\",\"label\":\"编辑\",\"position\":\"row\",\"buttonType\":\"primary\",\"permission\":\"system:user:manage\"},{\"action\":\"user-toggle-status\",\"label\":\"停用\",\"position\":\"row\",\"permission\":\"system:user:manage\"},{\"action\":\"user-reset-password\",\"label\":\"重置密码\",\"position\":\"row\",\"permission\":\"system:user:manage\"},{\"action\":\"user-assign-roles\",\"label\":\"分配角色\",\"position\":\"row\",\"permission\":\"system:user:manage\"}]','{\n  \"labelWidth\": \"auto\",\n  \"gridColumns\": 2,\n  \"fields\": [\n    { \"field\": \"institutionId\", \"label\": \"机构\", \"type\": \"select\", \"required\": true, \"gridSpan\": 1,\n      \"optionsLoader\": \"institutions\" },\n    { \"field\": \"username\", \"label\": \"账号\", \"type\": \"input\", \"required\": true, \"gridSpan\": 1,\n      \"disabledOn\": [\"edit\"], \"placeholder\": \"登录账号\" },\n    { \"field\": \"displayName\", \"label\": \"显示名称\", \"type\": \"input\", \"required\": true, \"gridSpan\": 1,\n      \"placeholder\": \"姓名/昵称\" },\n    { \"field\": \"phone\", \"label\": \"手机号\", \"type\": \"input\", \"gridSpan\": 1, \"maxlength\": 32 },\n    { \"field\": \"status\", \"label\": \"状态\", \"type\": \"select\", \"gridSpan\": 1,\n      \"optionsLoader\": \"status\", \"defaultValue\": \"active\" },\n    { \"field\": \"initialPassword\", \"label\": \"初始化密码\", \"type\": \"password\", \"gridSpan\": 1,\n      \"showOn\": [\"create\"], \"placeholder\": \"留空则使用默认初始密码\", \"maxlength\": 128 },\n    { \"field\": \"remark\", \"label\": \"备注\", \"type\": \"textarea\", \"gridSpan\": 2, \"maxlength\": 500 }\n  ]\n}','{\n      \"title\": \"用户列表\",\n      \"description\": \"支持创建、编辑、启停、重置密码、分配角色。\",\n      \"showCount\": true,\n      \"countFormat\": \"共 {total} 条\",\n      \"emptyText\": \"暂无数据\"\n    }','{\n      \"width\": \"640px\",\n      \"createTitle\": \"新增用户\",\n      \"editTitle\": \"编辑用户\",\n      \"submitText\": \"保存\",\n      \"cancelText\": \"取消\",\n      \"createMessage\": \"用户已创建\",\n      \"updateMessage\": \"用户已更新\",\n      \"reloadAfterSubmit\": true\n    }','active','系统设置-用户管理列表','2026-09-08 22:29:42',NULL,'2026-09-20 23:59:01',NULL,0);
INSERT INTO `sys_list_config` (`id`, `resource_code`, `resource_name`, `endpoint`, `page_size`, `columns_json`, `query_json`, `actions_json`, `form_json`, `page_json`, `dialog_json`, `status`, `remark`, `created_at`, `created_by`, `updated_at`, `updated_by`, `deleted`) VALUES (2,'system-roles','角色管理','/system/roles/page',10,'[{\"prop\":\"roleCode\",\"label\":\"角色编码\",\"width\":180},{\"prop\":\"roleName\",\"label\":\"角色名称\",\"minWidth\":180},{\"prop\":\"permissionCodes\",\"label\":\"权限\",\"minWidth\":300,\"renderer\":\"permissionTags\"},{\"prop\":\"status\",\"label\":\"状态\",\"width\":120,\"type\":\"dict\",\"dictType\":\"common_status\",\"tagTypeMap\":{\"active\":\"success\",\"disabled\":\"info\"}},{\"prop\":\"remark\",\"label\":\"备注\",\"minWidth\":200}]','[{\"field\":\"keyword\",\"label\":\"关键字\",\"type\":\"input\",\"placeholder\":\"角色编码/角色名称\"},{\"field\":\"status\",\"label\":\"状态\",\"type\":\"dict-select\",\"dictType\":\"common_status\"}]','[{\"action\":\"role-create\",\"label\":\"新增角色\",\"position\":\"toolbar\",\"buttonType\":\"primary\",\"permission\":\"system:role:manage\"},{\"action\":\"role-edit\",\"label\":\"编辑\",\"position\":\"row\",\"buttonType\":\"primary\",\"permission\":\"system:role:manage\"},{\"action\":\"role-assign-menus\",\"label\":\"分配菜单\",\"position\":\"row\",\"permission\":\"system:menu:manage\"},{\"action\":\"role-toggle-status\",\"label\":\"停用\",\"position\":\"row\",\"permission\":\"system:role:manage\"}]','{\n  \"labelWidth\": \"auto\",\n  \"gridColumns\": 2,\n  \"fields\": [\n    { \"field\": \"roleCode\", \"label\": \"角色编码\", \"type\": \"input\", \"required\": true, \"gridSpan\": 1,\n      \"disabledOn\": [\"edit\"], \"placeholder\": \"如 CAMPUS_ADMIN\" },\n    { \"field\": \"roleName\", \"label\": \"角色名称\", \"type\": \"input\", \"required\": true, \"gridSpan\": 1,\n      \"placeholder\": \"如 校区管理员\" },\n    { \"field\": \"status\", \"label\": \"状态\", \"type\": \"select\", \"gridSpan\": 1,\n      \"optionsLoader\": \"status\", \"defaultValue\": \"active\" },\n    { \"field\": \"permissionCodes\", \"label\": \"预设权限\", \"type\": \"permission-groups\", \"gridSpan\": 2 },\n    { \"field\": \"customPermissionCodes\", \"label\": \"补充权限码\", \"type\": \"textarea\", \"gridSpan\": 2,\n      \"placeholder\": \"逗号或换行分隔未知权限码\", \"rows\": 2 },\n    { \"field\": \"remark\", \"label\": \"备注\", \"type\": \"textarea\", \"gridSpan\": 2, \"maxlength\": 500 }\n  ]\n}','{\n      \"title\": \"角色列表\",\n      \"description\": \"支持角色维护,并可进一步分配菜单树。\",\n      \"showCount\": true,\n      \"countFormat\": \"共 {total} 条\",\n      \"emptyText\": \"暂无数据\"\n    }','{\n      \"width\": \"680px\",\n      \"createTitle\": \"新增角色\",\n      \"editTitle\": \"编辑角色\",\n      \"submitText\": \"保存\",\n      \"cancelText\": \"取消\",\n      \"createMessage\": \"角色已创建\",\n      \"updateMessage\": \"角色已更新\",\n      \"reloadAfterSubmit\": true\n    }','active','系统设置-角色管理列表','2026-09-08 22:29:42',NULL,'2026-09-11 00:52:29',NULL,0);
INSERT INTO `sys_list_config` (`id`, `resource_code`, `resource_name`, `endpoint`, `page_size`, `columns_json`, `query_json`, `actions_json`, `form_json`, `page_json`, `dialog_json`, `status`, `remark`, `created_at`, `created_by`, `updated_at`, `updated_by`, `deleted`) VALUES (3,'system-configs','系统参数','/system/config/page',10,'[{\"prop\":\"configKey\",\"label\":\"配置键\",\"minWidth\":200,\"showOverflowTooltip\":true},{\"prop\":\"displayName\",\"label\":\"显示名称\",\"minWidth\":140},{\"prop\":\"configValue\",\"label\":\"配置值\",\"minWidth\":160,\"showOverflowTooltip\":true},{\"prop\":\"valueType\",\"label\":\"值类型\",\"width\":100},{\"prop\":\"configGroup\",\"label\":\"分组\",\"width\":120,\"type\":\"map\",\"valueMap\":{\"general\":\"通用\",\"auth\":\"认证\",\"system\":\"系统\",\"business\":\"业务\"}},{\"prop\":\"isSystem\",\"label\":\"系统内置\",\"width\":100,\"type\":\"boolean\",\"trueLabel\":\"是\",\"falseLabel\":\"否\"},{\"prop\":\"sortOrder\",\"label\":\"排序\",\"width\":80},{\"prop\":\"status\",\"label\":\"状态\",\"width\":110,\"type\":\"dict\",\"dictType\":\"common_status\",\"tagTypeMap\":{\"active\":\"success\",\"disabled\":\"info\"}},{\"prop\":\"description\",\"label\":\"说明\",\"minWidth\":180,\"showOverflowTooltip\":true}]','[{\"field\":\"keyword\",\"label\":\"关键字\",\"type\":\"input\",\"placeholder\":\"配置键/显示名称/说明\"},{\"field\":\"configGroup\",\"label\":\"分组\",\"type\":\"select\",\"options\":[{\"label\":\"通用\",\"value\":\"general\"},{\"label\":\"认证\",\"value\":\"auth\"},{\"label\":\"系统\",\"value\":\"system\"},{\"label\":\"业务\",\"value\":\"business\"}]},{\"field\":\"status\",\"label\":\"状态\",\"type\":\"dict-select\",\"dictType\":\"common_status\"}]','[{\"action\":\"config-create\",\"label\":\"新增参数\",\"position\":\"toolbar\",\"buttonType\":\"primary\",\"permission\":\"system:config:write\"},{\"action\":\"config-edit\",\"label\":\"编辑\",\"position\":\"row\",\"buttonType\":\"primary\",\"permission\":\"system:config:write\"},{\"action\":\"config-delete\",\"label\":\"删除\",\"position\":\"row\",\"buttonType\":\"danger\",\"permission\":\"system:config:write\"}]','{\n  \"labelWidth\": \"auto\",\n  \"gridColumns\": 2,\n  \"fields\": [\n    { \"field\": \"configKey\", \"label\": \"配置键\", \"type\": \"input\", \"required\": true, \"gridSpan\": 1,\n      \"disabledOn\": [\"edit\"], \"placeholder\": \"如 app.name\", \"maxlength\": 128 },\n    { \"field\": \"displayName\", \"label\": \"显示名称\", \"type\": \"input\", \"required\": true, \"gridSpan\": 1,\n      \"maxlength\": 64 },\n    { \"field\": \"configValue\", \"label\": \"配置值\", \"type\": \"input\", \"required\": true, \"gridSpan\": 1,\n      \"placeholder\": \"当前生效值\" },\n    { \"field\": \"valueType\", \"label\": \"值类型\", \"type\": \"select\", \"required\": true, \"gridSpan\": 1,\n      \"disabledOn\": [\"edit\"], \"options\": [\n        { \"label\": \"字符串\", \"value\": \"string\" },\n        { \"label\": \"整数\", \"value\": \"int\" },\n        { \"label\": \"布尔\", \"value\": \"boolean\" },\n        { \"label\": \"JSON\", \"value\": \"json\" }\n      ], \"defaultValue\": \"string\" },\n    { \"field\": \"configGroup\", \"label\": \"配置分组\", \"type\": \"input\", \"required\": true, \"gridSpan\": 1,\n      \"disabledOn\": [\"edit\"], \"placeholder\": \"如 general/auth/system/business\" },\n    { \"field\": \"sortOrder\", \"label\": \"排序\", \"type\": \"number\", \"gridSpan\": 1, \"min\": 0, \"max\": 9999,\n      \"defaultValue\": 0 },\n    { \"field\": \"isSystem\", \"label\": \"系统内置\", \"type\": \"switch\", \"gridSpan\": 1, \"showOn\": [\"create\"],\n      \"defaultValue\": false },\n    { \"field\": \"status\", \"label\": \"状态\", \"type\": \"select\", \"gridSpan\": 1,\n      \"optionsLoader\": \"status\", \"defaultValue\": \"active\" },\n    { \"field\": \"defaultValue\", \"label\": \"默认值\", \"type\": \"input\", \"gridSpan\": 2 },\n    { \"field\": \"description\", \"label\": \"配置说明\", \"type\": \"textarea\", \"gridSpan\": 2, \"maxlength\": 500 }\n  ]\n}','{\n      \"title\": \"系统参数\",\n      \"description\": \"维护全局键值参数(token 有效期等),支持新增、编辑与删除。\",\n      \"showCount\": true,\n      \"countFormat\": \"共 {total} 条\",\n      \"emptyText\": \"暂无数据\"\n    }','{\n      \"width\": \"640px\",\n      \"createTitle\": \"新增系统参数\",\n      \"editTitle\": \"编辑系统参数\",\n      \"submitText\": \"保存\",\n      \"cancelText\": \"取消\",\n      \"createMessage\": \"系统参数已创建\",\n      \"updateMessage\": \"系统参数已更新\",\n      \"reloadAfterSubmit\": true\n    }','active','系统设置-系统参数列表','2026-09-08 22:29:42',NULL,'2026-09-11 00:52:29',NULL,0);
